// INF-24: Weekly self-improvement loop — review corrections, promote patterns, update MEMORY.md
// Fixed: uses helpers.httpRequest instead of child_process
// Also posts results to Discord #self-improvement channel

const DISCORD_TOKEN = 'MTQ4NjA0MTQ3MTUwNDM1MTMxMw.GoiBGW.VS2nGK2X1LMjMjkOBL9NqrOVeUdZfbGo9HdAyo';
const DISCORD_CHANNEL = '1488963474045276202'; // #self-improvement-actions
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';
const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';

const prompt = `Weekly self-improvement loop. Do ALL of the following:

1. Read ~/self-improving/corrections.md — identify patterns corrected 3+ times this week
2. Promote confirmed 3x patterns to HOT tier in ~/self-improving/memory.md
3. Check ~/self-improving/memory.md for patterns not used in 30 days → demote to WARM tier
4. Read ~/self-improving/reflections.md — distill key lessons into MEMORY.md
5. For each agent workspace that exists (builder, tester, designer, ops, po, auditor, scout):
   - Read that agent's self-improving/corrections.md if it exists
   - Note any patterns that should be promoted
6. Write a dated summary entry to ~/self-improving/reflections.md confirming loop ran

After completing, post a Discord message to https://discord.com/api/v10/channels/1488963474045276202/messages (Authorization: Bot ${DISCORD_TOKEN}) with this format:
🧠 **Weekly Self-Improvement Summary — [date]**

**Patterns Promoted (HOT):**
• [list each]

**Patterns Demoted (WARM/archived):**
• [list each or "none"]

**Key Lessons This Week:**
• [2-3 key lessons from reflections.md]

**Agent-Specific Updates:**
• [any notable corrections from agent workspaces]`;

try {
  await helpers.httpRequest({
    method: 'POST', url: TRIGGER_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentId: 'main', message: prompt })
  });
  return [{ json: { action: 'self_improvement_triggered', timestamp: new Date().toISOString() } }];
} catch(e) {
  // Post failure to Discord
  await helpers.httpRequest({
    method: 'POST',
    url: 'https://discord.com/api/v10/channels/' + DISCORD_CHANNEL + '/messages',
    headers: { Authorization: 'Bot ' + DISCORD_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: '⚠️ Self-improvement loop failed to trigger: ' + e.message })
  });
  return [{ json: { action: 'error', error: e.message } }];
}
